def rect(sl,x,y,w,h,color):
 sh=sl.shapes.add_shape(1, Inches(x), Inches(y), Inches(w), Inches(h)); sh.fill.solid();sh.fill.fore_color.rgb=RGBColor.from_string(color);sh.line.fill.background();return sh
def textbox(sl,x,y,w,h,text,size=22,color=WHITE,bold=False,rtl=True):
 box=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));tf=box.text_frame;tf.word_wrap=True
 tf.margin_left=Inches(.05);tf.margin_right=Inches(.05);tf.margin_top=Inches(.02);tf.margin_bottom=Inches(.02)
 p=tf.paragraphs[0];p.alignment=PP_ALIGN.RIGHT if rtl else PP_ALIGN.LEFT
 pPr=p._p.get_or_add_pPr();pPr.set('rtl','1' if rtl else '0')
 run=p.add_run();run.text=text;run.font.name='Noto Sans Arabic';run.font.size=Pt(size);run.font.bold=bold;run.font.color.rgb=RGBColor.from_string(color)
 rp=run._r.get_or_add_rPr();rp.set('lang','ar-EG');cs=OxmlElement('a:cs');cs.set('typeface','Noto Sans Arabic');rp.append(cs)
 return box
